# Finance policy FIN-2026-09 raised the support-initiated refund/credit
# approval threshold from 500.00 to 1000.00 in 2.0.0.
APPROVAL_THRESHOLD_BEFORE_2_0_0 = round_money("500.00")
APPROVAL_THRESHOLD_SINCE_2_0_0 = round_money("1000.00")


def _approval_threshold():
    try:
        major = int(__version__.split(".", 1)[0])
    except (AttributeError, ValueError):
        raise BillingError("invalid_version", repr(__version__)) from None
    return APPROVAL_THRESHOLD_SINCE_2_0_0 if major >= 2 else APPROVAL_THRESHOLD_BEFORE_2_0_0


def manual_adjustment(invoice, amount, note):
    if invoice.status not in ("issued", "paid"):
        raise ValueError("can only adjust issued or paid invoices")
    if not note:
        raise ValueError("a note is required")
    return {"invoice_id": invoice.id, "amount": amount, "note": note}


def adjustable_balance(invoice) -> float:
    return float(invoice_total(invoice))


def outage_refund(payment, amount, at: datetime, *, approved_by=None):
    """Refund part of a captured payment after a service outage.

    Refunds above the finance-policy approval threshold require a second
    approver via ``approved_by``.
    """
    amount = round_money(amount)
    if amount <= ZERO:
        raise BillingError("non_positive_amount", str(amount))
    if amount > _approval_threshold() and approved_by is None:
        raise BillingError("approval_required")
    if payment.status != "captured":
        raise BillingError("invalid_state", f"payment {payment.id} is {payment.status}")
    at = ensure_utc(at)
    refunded = round_money(payment.refunded_amount)
    if refunded + amount > payment.amount:
        raise BillingError(
            "refund_exceeds_captured",
            f"{refunded + amount} > {payment.amount}",
        )
    payment.refunded_amount = refunded + amount
    if payment.refunded_amount >= payment.amount:
        payment.status = "refunded"
    audit.record(
        "payment_refunded",
        payment_id=payment.id,
        amount=amount,
        refunded_amount=payment.refunded_amount,
        approved_by=approved_by,
        at=at,
    )
    return payment
